local ShovelMaker = {}
local PRODUCTS = {
    iron_shovel = { name = "Železna lopata", ironCost = 2, woodCost = 3, leatherCost = 1, time = 4, cost = 110, prestige = 2, happiness = 1, description = "Železna lopata za izkopavanje." },
    bronze_shovel = { name = "Bronasta lopata", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 1, time = 6, cost = 280, prestige = 4, happiness = 2, description = "Bronasta lopata za trdo zemljo." },
    silver_shovel = { name = "Srebrna lopata", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 10, cost = 720, prestige = 8, happiness = 3, description = "Srebrna lopata za plemiške vrtove." },
    gilded_shovel = { name = "Pozlačena lopata", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 14, cost = 1600, prestige = 16, happiness = 4, description = "Pozlačena lopata za dvorne izkope." },
    jewel_set_shovel = { name = "Draguljasta lopata", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 18, cost = 3500, prestige = 30, happiness = 6, description = "Draguljasta lopata za kraljeve izkope." },
    royal_sovereign_shovel = { name = "Kraljevski suverena lopata", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 25, cost = 7800, prestige = 60, happiness = 12, description = "Suverena lopata z biseri za krono." },
}
local BUILDINGS = {
    shovel_workshop = { name = "Lopatarska delavnica", cost = { gold = 280, wood = 180, stone = 100, iron = 5 }, upkeep = 5, qualityBonus = 5 },
    shoveler_house = { name = "Lopatarska hiša", cost = { gold = 1050, wood = 340, stone = 220, silver = 6, iron = 6 }, upkeep = 22, qualityBonus = 18 },
    master_shovel_atelier = { name = "Mojstrski lopatarski atelje", cost = { gold = 2800, wood = 400, stone = 460, silver = 30, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    sovereign_excavation_palace = { name = "Suverena izkopavalna palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 78, jewel = 17 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
ShovelMaker.ironStock = 12; ShovelMaker.bronzeStock = 10; ShovelMaker.woodStock = 14; ShovelMaker.leatherStock = 10; ShovelMaker.silverStock = 8; ShovelMaker.goldStock = 6; ShovelMaker.jewelStock = 4; ShovelMaker.pearlStock = 4
ShovelMaker.productStock = {}; ShovelMaker.buildings = {}; ShovelMaker.maker = nil; ShovelMaker.activeMaking = {}; ShovelMaker.totalProducts = 0; ShovelMaker.dayTimer = 0
function ShovelMaker.init() ShovelMaker.ironStock=12; ShovelMaker.bronzeStock=10; ShovelMaker.woodStock=14; ShovelMaker.leatherStock=10; ShovelMaker.silverStock=8; ShovelMaker.goldStock=6; ShovelMaker.jewelStock=4; ShovelMaker.pearlStock=4; ShovelMaker.productStock={}; ShovelMaker.buildings={}; ShovelMaker.maker=nil; ShovelMaker.activeMaking={}; ShovelMaker.totalProducts=0; ShovelMaker.dayTimer=0; print("[ShovelMaker] Royal Shovel Maker System initialized (6 products, 4 buildings)") end
function ShovelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ShovelMaker.maker={name=n or ("Lopatar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatar najet: %s (spretnost: %d)",ShovelMaker.maker.name,s),"success") end; return true end
function ShovelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ShovelMaker.build(id) local ok,e=ShovelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ShovelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ShovelMaker.getQualityBonus() local b=0; for _,bd in ipairs(ShovelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ShovelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ShovelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ShovelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ShovelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ShovelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ShovelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ShovelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ShovelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ShovelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ShovelMaker.buildings==0 then return false,"Potrebna lopatarska delavnica" end; if not ShovelMaker.maker then return false,"Potreben lopatar" end; return true end
function ShovelMaker.make(pt,qty) qty=qty or 1; local ok,e=ShovelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ShovelMaker.ironStock=ShovelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ShovelMaker.bronzeStock=ShovelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ShovelMaker.woodStock=ShovelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ShovelMaker.leatherStock=ShovelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ShovelMaker.silverStock=ShovelMaker.silverStock-d.silverCost*qty end; if d.goldCost then ShovelMaker.goldStock=ShovelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ShovelMaker.jewelStock=ShovelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ShovelMaker.pearlStock=ShovelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ShovelMaker.maker then t=math.max(1,t-math.floor(ShovelMaker.maker.skill/13)) end; table.insert(ShovelMaker.activeMaking,{id="shovel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ShovelMaker.completeMaking(m) local q=1.0+(ShovelMaker.getQualityBonus()/100); if ShovelMaker.maker then q=q+(ShovelMaker.maker.skill/140) end; q=math.min(2.5,q); ShovelMaker.productStock[m.productType]=(ShovelMaker.productStock[m.productType] or 0)+m.quantity; ShovelMaker.totalProducts=ShovelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ShovelMaker.maker then ShovelMaker.maker.itemsMade=ShovelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ShovelMaker.maker.skill=math.min(100,ShovelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopata izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"shovel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ShovelMaker.update(dt) if not _G.state then return end; ShovelMaker.dayTimer=ShovelMaker.dayTimer+dt; if ShovelMaker.dayTimer>=30 then ShovelMaker.dayTimer=0; for i=#ShovelMaker.activeMaking,1,-1 do local m=ShovelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ShovelMaker.completeMaking(m); table.remove(ShovelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ShovelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ShovelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ShovelMaker.getStats() return {ironStock=ShovelMaker.ironStock,bronzeStock=ShovelMaker.bronzeStock,woodStock=ShovelMaker.woodStock,leatherStock=ShovelMaker.leatherStock,silverStock=ShovelMaker.silverStock,goldStock=ShovelMaker.goldStock,jewelStock=ShovelMaker.jewelStock,pearlStock=ShovelMaker.pearlStock,productStock=ShovelMaker.productStock,numBuildings=#ShovelMaker.buildings,hasMaker=ShovelMaker.maker~=nil,makerName=ShovelMaker.maker and ShovelMaker.maker.name or "—",makerSkill=ShovelMaker.maker and ShovelMaker.maker.skill or 0,activeMaking=#ShovelMaker.activeMaking,totalProducts=ShovelMaker.totalProducts} end
return ShovelMaker
